// D2 SP DERIVED COPY of experiments/P1-pocket-top/rtl/p1_load_wq.sv (generated by make_d2_derived.py): module renamed to
// d2_load_wq3, a third loader input (c_*, slot 3 = sprite ROM) with its own SDRAM base. The host writes one slot at a
// time, so the three strobes never coincide in practice; a coincidence is counted in n_collide (as a/b before).
//
// p1_load_wq: merges the two APF slot loaders (data_loader, 16-bit words, clk_sys domain pulses) into upstream sdram.sv's
// download write port (clk_ram). sdram.sv latches one transaction per wr_req RISING edge into a single mailbox, so a second
// write issued before the first is acknowledged would overwrite it; this queue therefore holds wr_req high until wr_ack and
// issues one write at a time. clk_sys = clk_ram/2, phase-aligned (synchronous): a one-clk_sys write_en is seen on two clk_ram
// edges and is taken on its rising edge. P1 Pocket-top simulation (stage S2).
module d2_load_wq3 #(
    parameter int DEPTH_LOG2 = 4
) (
    input              clk,           // clk_ram
    input              rst,
    input              a_en,          // slot 1 (program ROM) loader write strobe
    input       [24:0] a_addr,        // byte offset in the slot
    input       [15:0] a_data,
    input              b_en,          // slot 2 (tile ROM)
    input       [24:0] b_addr,
    input       [15:0] b_data,
    input              c_en,          // slot 3 (sprite ROM)
    input       [24:0] c_addr,
    input       [15:0] c_data,
    input       [24:0] a_base,        // SDRAM byte base of each slot
    input       [24:0] b_base,
    input       [24:0] c_base,
    output reg         wr_req = 1'b0,
    output reg  [24:1] wr_addr = 0,
    output reg  [15:0] wr_din = 0,
    output       [1:0] wr_be,
    input              wr_ack,
    output             empty,
    output reg  [31:0] n_in = 0,
    output reg  [31:0] n_out = 0,
    output reg  [31:0] n_overflow = 0,
    output reg  [31:0] n_collide = 0,
    output reg  [15:0] max_fill = 0
);
assign wr_be = 2'b11;
localparam int D = 1 << DEPTH_LOG2;
reg [39:0] mem [0:D-1];
reg [DEPTH_LOG2:0] wp = 0, rp = 0;
wire [DEPTH_LOG2:0] fill = wp - rp;
assign empty = (wp == rp) && !wr_req;
reg a_d = 1'b0, b_d = 1'b0, c_d = 1'b0, ack_d = 1'b0;
wire a_rise = a_en && !a_d, b_rise = b_en && !b_d, c_rise = c_en && !c_d;
always @(posedge clk) begin
    a_d <= a_en; b_d <= b_en; c_d <= c_en; ack_d <= wr_ack;
    if (rst) begin
        wp <= 0; rp <= 0; wr_req <= 1'b0;
    end else begin
        if ((a_rise && b_rise) || (a_rise && c_rise) || (b_rise && c_rise)) n_collide <= n_collide + 1;
        if (a_rise || b_rise || c_rise) begin
            if (fill == D[DEPTH_LOG2:0]) n_overflow <= n_overflow + 1;
            else begin
                mem[wp[DEPTH_LOG2-1:0]] <= a_rise ? {24'((a_base + a_addr) >> 1), a_data} : b_rise ? {24'((b_base + b_addr) >> 1), b_data}
                                                    : {24'((c_base + c_addr) >> 1), c_data};
                wp <= wp + 1'd1;
                n_in <= n_in + 1;
            end
        end
        if (16'(fill) > max_fill) max_fill <= 16'(fill);
        if (wr_req) begin
            if (wr_ack && !ack_d) begin wr_req <= 1'b0; n_out <= n_out + 1; end
        end else if (wp != rp && !wr_ack) begin
            {wr_addr, wr_din} <= mem[rp[DEPTH_LOG2-1:0]];
            rp <= rp + 1'd1;
            wr_req <= 1'b1;
        end
    end
end
endmodule
